import { ConflictError, ValidationError } from "./errors";

export const TASK_STATUSES = ["todo", "in_progress", "done"] as const;
export type TaskStatus = (typeof TASK_STATUSES)[number];

export function isTaskStatus(value: unknown): value is TaskStatus {
  return typeof value === "string" && (TASK_STATUSES as readonly string[]).includes(value);
}

export interface Task {
  readonly id: string;
  readonly projectId: string;
  readonly title: string;
  readonly description: string;
  readonly dueDate: Date | null;
  readonly status: TaskStatus;
  readonly assigneeId: string | null;
}

export interface NewTask {
  id: string;
  projectId: string;
  title: string;
  description: string;
  dueDate?: Date | null;
  status?: TaskStatus;
  assigneeId?: string | null;
}

export function createTask(input: NewTask): Task {
  const title = input.title.trim();
  if (title === "") throw new ValidationError("Task title is required");
  if (input.dueDate && Number.isNaN(input.dueDate.getTime())) {
    throw new ValidationError("Due date is invalid");
  }
  return {
    id: input.id,
    projectId: input.projectId,
    title,
    description: input.description,
    dueDate: input.dueDate ?? null,
    status: input.status ?? "todo",
    assigneeId: input.assigneeId ?? null,
  };
}

export function assignTask(task: Task, assigneeId: string): Task {
  return { ...task, assigneeId };
}

export function markTaskDone(task: Task): Task {
  if (task.status === "done") throw new ConflictError("Task is already done");
  return { ...task, status: "done" };
}

